  def genTestCase(observationKind: ObservationKind.Type, preContainer: Option[String], postContainer: Option[String], testNameSuffix: Option[String]): ST = {
    val tq = "\"\"\""
    val suffix: String =
      if (testNameSuffix.nonEmpty) testNameSuffix.get
      else ""

    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.StationCargoTransferVerificationSystem_Instance_supervisorProcess_requestQualifier_postInit =>
        return (st"""// Begin test cases for StationCargoTransferVerificationSystem_Instance_supervisorProcess_requestQualifier_postInit
                    |
                    |test(s"StationCargoTransferVerificationSystem_Instance_supervisorProcess_requestQualifier_postInit: Check Post-condition$suffix") {
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val postContainer = scp_candidate.JSON.toStation_Cargo_Transfer_Verification_SupervisorRequestQualifier_supervisorProcess_requestQualifier_PostState_Container_PS(postJson).left
                    |  assert(scp_candidate.Station_Cargo_Transfer_Verification_Supervisor.RequestQualifier_supervisorProcess_requestQualifier_GumboX.inititialize_IEP_Post_Container(postContainer))
                    |}
                    |// End test cases for StationCargoTransferVerificationSystem_Instance_supervisorProcess_requestQualifier_postInit""")
      case scp_candidate.runtimemonitor.ObservationKind.StationCargoTransferVerificationSystem_Instance_supervisorProcess_requestQualifier_postCompute =>
        return (st"""// Begin test cases for StationCargoTransferVerificationSystem_Instance_supervisorProcess_requestQualifier_postCompute
                    |
                    |test(s"StationCargoTransferVerificationSystem_Instance_supervisorProcess_requestQualifier_postCompute: Check Post-condition$suffix") {
                    |  val preJson: String = st${tq}${preContainer.get}${tq}.render
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val preContainer = scp_candidate.JSON.toStation_Cargo_Transfer_Verification_SupervisorRequestQualifier_supervisorProcess_requestQualifier_PreState_Container_PS(preJson).left
                    |  val postContainer = scp_candidate.JSON.toStation_Cargo_Transfer_Verification_SupervisorRequestQualifier_supervisorProcess_requestQualifier_PostState_Container_PS(postJson).left
                    |  if (verbose) {
                    |    println("Pre-State Values:")
                    |    println(s"  $$preContainer")
                    |    println("Post-State Values:")
